/*
 AgroSmart Insights - WF1
 Normalizador de boletines MIDAGRI - GMML

 Nodo: normalizar
 Language: JavaScript
 Mode: Run Once for All Items

 Lee el texto de Extract from File1.
 Verifica la fecha del boletin.
 Extrae productos, precios, unidades y volumenes.
*/

const entrada = $input.all();

const fechaObjetivo = String(
  $('Code - preparar fecha MIDAGRI')
    .first().json.fecha_objetivo ?? ''
).slice(0, 10);

if (!/^\d{4}-\d{2}-\d{2}$/.test(fechaObjetivo)) {
  throw new Error('fecha_objetivo invalida');
}

// MESES
const meses = {
  enero: 1,
  febrero: 2,
  marzo: 3,
  abril: 4,
  mayo: 5,
  junio: 6,
  julio: 7,
  agosto: 8,
  septiembre: 9,
  setiembre: 9,
  octubre: 10,
  noviembre: 11,
  diciembre: 12
};

// UNIDADES COMERCIALES
const unidades = [
  'Atado Grande',
  'Cajon Chico',
  'Saco Chico',
  'Kilogramo',
  'Paquete',
  'Docena',
  'Ciento',
  'Cajon',
  'Atado',
  'Bolsa',
  'Saco',
  'Mano',
  'Unidad'
];

const esc = s =>
  s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const unidadRegex = unidades.map(esc).join('|');

const numero = String.raw`\d+(?:[.,]\d+)?`;
const celda = String.raw`(?::|${numero})`;

// ORDEN REAL DEL PDF:
// producto
// volumen ayer
// volumen hoy
// promedio volumen 7 dias
// promedio volumen 4 viernes
// unidad
// equivalencia kg
// precio ayer
// precio hoy
// promedio precio 7 dias

const patron = new RegExp(
  String.raw`^(.+?)\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${celda})\s+` +
  String.raw`(${unidadRegex})\s+` +
  String.raw`(${numero})\s+` +
  String.raw`(${numero})\s+` +
  String.raw`(${numero})\s+` +
  String.raw`(${numero})\s*$`,
  'i'
);

// Convertir valores del PDF
function n(valor) {
  if (valor === ':') return null;
  return Number(valor.replace(',', '.'));
}

const salida = [];
const noReconocidas = [];

// PROCESAR PDFs
for (const item of entrada) {

  const texto = String(item.json.text ?? '');

  if (!texto.trim()) {
    throw new Error(
      'Extract from File1 no entrego texto'
    );
  }

  // VALIDAR FECHA REAL DEL BOLETIN
  const cabecera = texto.match(
    /\b(\d{1,2})\s+de\s+([a-záéíóú]+)\s+de\s+(20\d{2})\b/i
  );

  if (!cabecera) {
    throw new Error(
      'No se pudo verificar la fecha del PDF'
    );
  }

  const mm = meses[cabecera[2].toLowerCase()];

  if (!mm) {
    throw new Error(
      'Mes no reconocido: ' + cabecera[2]
    );
  }

  const fechaPDF =
    `${cabecera[3]}-` +
    `${String(mm).padStart(2, '0')}-` +
    `${cabecera[1].padStart(2, '0')}`;

  if (fechaPDF !== fechaObjetivo) {
    throw new Error(
      `El PDF corresponde a ${fechaPDF}, ` +
      `pero se solicito ${fechaObjetivo}`
    );
  }

  // SEPARAR PRODUCTOS POR LINEA

  // SEPARAR PRODUCTOS POR LINEA
  const lineas = texto
    .split(/\r?\n/)
    .map(s => s.replace(/\s+/g, ' ').trim())
    .filter(Boolean);

  // Detecta una fila que empieza directamente
  // con los cuatro valores de volumen.
  const filaSinNombre = new RegExp(
    String.raw`^${celda}\s+${celda}\s+` +
    String.raw`${celda}\s+${celda}\s+` +
    String.raw`(?:${unidadRegex})\s+` +
    String.raw`${numero}\s+${numero}\s+` +
    String.raw`${numero}\s+${numero}\s*$`,
    'i'
  );

  // Procesar las filas
  for (let i = 0; i < lineas.length; i++) {

    let linea = lineas[i];
    let m = linea.match(patron);

    // Si falta el nombre, buscarlo en la línea anterior.
    if (!m && filaSinNombre.test(linea) && i > 0) {

      const nombreAnterior = lineas[i - 1];

      // No utilizar cabeceras ni otra fila numérica
      // como si fueran nombres de productos.
      const esCabecera =
        /^(Fuente|Elaboraci[oó]n|Productos|Precio|Masa|Unidad|Equiv\.|TOTAL|PROMEDIO)/i
          .test(nombreAnterior);

      const tieneUnidad =
        new RegExp(`\\b(?:${unidadRegex})\\b`, 'i')
          .test(nombreAnterior);

      const esNumerico =
        /^[\d\s:.,]+$/.test(nombreAnterior);

      if (
        !esCabecera &&
        !tieneUnidad &&
        !esNumerico &&
        nombreAnterior.length > 2
      ) {
        const reconstruida =
          nombreAnterior + ' ' + linea;

        const coincidencia =
          reconstruida.match(patron);

        if (coincidencia) {
          linea = reconstruida;
          m = coincidencia;
        }
      }
    }


    if (!m) {

      // Detectar posibles productos no interpretados
      if (
        /\b(?:Kilogramo|Docena|Cajon|Atado|Paquete|Bolsa|Ciento|Saco|Unidad|Mano)\b/i
          .test(linea) &&
        !/^(Masa|Precio|Unidad de|Productos|Equiv\.|Elaboraci[oó]n|Fuente)/i
          .test(linea)
      ) {
        noReconocidas.push(linea);
      }

      continue;
    }

    // NOMBRE DEL PRODUCTO
    const original = m[1].trim();

    // Quitar notas 1/ y 2/ solo del nombre normalizado
    const producto = original
      .replace(/\s+[12]\/\s*$/, '')
      .trim();

    // VOLUMEN HOY EN TONELADAS
    const volumenHoy = n(m[3]);

    // EQUIVALENCIA COMERCIAL
    const equivalencia = n(m[7]);

    // PRECIO HOY
    const precioHoy = n(m[9]);

    // VALIDACIONES
    if (
      !producto ||
      precioHoy === null ||
      precioHoy < 0 ||
      equivalencia === null ||
      equivalencia <= 0 ||
      (volumenHoy !== null && volumenHoy < 0)
    ) {
      throw new Error(
        'Registro invalido: ' + linea
      );
    }

    // GENERAR REGISTRO PARA POSTGRESQL
    salida.push({
      json: {

        fecha: fechaPDF,

        producto: producto,

        producto_original: original,

        mercado: 'GMML',

        unidad: m[6],

        equivalencia_kg: equivalencia,

        precio: precioHoy,

        precio_ayer: n(m[8]),

        precio_promedio_7: n(m[10]),

        // El PDF ya expresa las masas en toneladas
        volumen: volumenHoy,

        volumen_t: volumenHoy,

        volumen_kg:
          volumenHoy === null
            ? null
            : volumenHoy * 1000,

        volumen_ayer_t: n(m[2]),

        volumen_promedio_7_t: n(m[4]),

        volumen_promedio_4_viernes_t: n(m[5]),

        fuente: 'MIDAGRI'
      }
    });
  }
}

// EVITAR INGESTAS INCOMPLETAS
if (noReconocidas.length > 0) {
  throw new Error(
    'Hay filas que no se pudieron interpretar. ' +
    'No insertar. Ejemplos: ' +
    noReconocidas.slice(0, 3).join(' | ')
  );
}

// CONTROL DE CANTIDAD DE PRODUCTOS
if (salida.length < 50 || salida.length > 120) {
  throw new Error(
    `Cantidad inesperada de productos: ${salida.length}`
  );
}

// CONTROL DE DUPLICADOS
const claves = new Set();

for (const item of salida) {
  const r = item.json;

  const clave = [
    r.fecha,
    r.producto,
    r.mercado,
    r.unidad
  ].join('|');

  if (claves.has(clave)) {
    throw new Error(
      'Producto duplicado: ' + clave
    );
  }

  claves.add(clave);
}

// ENTREGAR PRODUCTOS
return salida;

