  if (!clima?.daily?.time) {
    continue;
  }

  const fechas = clima.daily.time;

  for (let j = 0; j < fechas.length; j++) {

    const tMax =
      clima.daily?.temperature_2m_max?.[j] ??
      clima.daily?.temperature_max?.[j] ??
      null;

    const tMin =
      clima.daily?.temperature_2m_min?.[j] ??
      clima.daily?.temperature_min?.[j] ??
      null;

    // Promedio simple para tu columna "temperatura"
    let temperatura = null;

    if (tMax !== null && tMin !== null) {
      temperatura = (Number(tMax) + Number(tMin)) / 2;
    }

    salida.push({
      json: {
        fecha: fechas[j],

        ubicacion:
