/*
 AgroSmart WF1
 Validar correspondencias con productos_maestro

 Detiene el flujo si existen:
 - Productos sin ID maestro
 - Coincidencias ambiguas
 - Registros con valores invalidos
*/

const registros = $input.all().map(item => item.json);

if (registros.length === 0) {
  throw new Error('No se recibieron registros.');
}

// Recuperamos los campos originales del normalizador
const originales = $('normalizar').all().map(x => x.json);

function clave(r) {
  return [
    r.fecha,
    r.producto,
    r.mercado,
    r.unidad
  ].join('|');
}

const mapaOriginal = new Map(
  originales.map(r => [clave(r), r])
);

const errores = [];
const resultado = [];

function numero(valor) {
  if (valor === null || valor === undefined || valor === '') {
    return null;
  }
  const n = Number(valor);
  return Number.isFinite(n) ? n : null;
}

for (const r of registros) {

  const original = mapaOriginal.get(clave(r));

  if (!original) {
    errores.push(`Registro original no encontrado: ${r.producto}`);
    continue;
  }

  if (
    r.estado_mapeo !== 'CORRECTO' ||
    numero(r.cantidad_coincidencias) !== 1 ||
    numero(r.producto_id) === null
  ) {
    errores.push(
      `${r.producto}: ${r.estado_mapeo} ` +
      `(coincidencias: ${r.cantidad_coincidencias})`
    );
    continue;
  }

  const precio = numero(r.precio);
  const volumen = numero(r.volumen_t);
  const equivalencia = numero(r.equivalencia_kg);

  if (
    precio === null ||
    precio < 0 ||
    equivalencia === null ||
    equivalencia <= 0 ||
    (volumen !== null && volumen < 0)
  ) {
    errores.push(`Valores invalidos: ${r.producto}`);
    continue;
  }

  resultado.push({
    json: {
      ...original,

      producto: r.nombre_canonico,
      producto_id: numero(r.producto_id),

      precio,
      equivalencia_kg: equivalencia,
      volumen: volumen,
      volumen_t: volumen,
      volumen_kg: volumen === null ? null : volumen * 1000,

      estado_mapeo: 'CORRECTO'
    }
  });
}

// Comprobar que no se hayan perdido registros
if (resultado.length !== originales.length) {
  errores.push(
    `Se recibieron ${originales.length} originales, ` +
    `pero solo ${resultado.length} fueron validados.`
  );
}

if (errores.length > 0) {
  throw new Error(
    'Validacion de mapeo fallida:\n' +
    errores.join('\n')
  );
}

return resultado;

/*
 AgroSmart Insights - WF0
 Parser de precios MMF2
 Formatos horizontal y vertical

 Fuente: MIDAGRI - SISAP GMML/MMF2
 No modifica PostgreSQL.
*/

const items = $input.all();
const resultados = [];
const errores = [];
const vistos = new Set();

let horizontales = 0;
let verticales = 0;
let mercadosDetectados = 0;

// ===========================================
// 1. OBTENER FECHA REAL DEL PDF
// ===========================================

const nombrePDF =
  $('HTTP Request - descargar PDF por Tunnel1')
    .first().binary.data.fileName;

const meses = {
  ene: '01', feb: '02', mar: '03',
  abr: '04', may: '05', jun: '06',
  jul: '07', ago: '08', sep: '09',
  set: '09', oct: '10', nov: '11',
  dic: '12'
};

const coincidenciaFecha = nombrePDF.match(
  /^sisap-gmml-mm2-(\d{2})([a-z]{3})(\d{2})\.pdf$/i
);

if (!coincidenciaFecha) {
  throw new Error(
    'Nombre del PDF no reconocido: ' + nombrePDF
  );
}

const mesPDF = meses[
  coincidenciaFecha[2].toLowerCase()
];

if (!mesPDF) {
  throw new Error('Mes del PDF no reconocido');
}

const fechaObjetivo =
  `20${coincidenciaFecha[3]}-${mesPDF}-${coincidenciaFecha[1]}`;

const fechaSolicitada = String(
  $('Code - preparar fecha MIDAGRI1')
    .first().json.fecha_objetivo ?? ''
).slice(0, 10);

if (fechaObjetivo !== fechaSolicitada) {
  throw new Error(
    `Fecha incorrecta. PDF: ${fechaObjetivo}. ` +
    `Solicitada: ${fechaSolicitada}`
  );
}

// ===========================================
// 2. FUNCIONES AUXILIARES
// ===========================================

function numero(valor) {
  const texto = String(valor ?? '').trim();

  if (!/^\d+(?:[.,]\d+)?$/.test(texto)) {
    return null;
  }

  const n = Number(texto.replace(',', '.'));

  return Number.isFinite(n) ? n : null;
}

function esPorcentaje(valor) {
  return /^[-+]?\d+(?:[.,]\d+)?%$/.test(
    String(valor ?? '').trim()
  );
}

function validarColumnas(valores) {
  return (
    valores.length === 12 &&
    esPorcentaje(valores[2]) &&
    esPorcentaje(valores[11]) &&
    valores.every((v, i) =>
      (i === 2 || i === 11)
        ? esPorcentaje(v)
        : numero(v) !== null
    )
  );
}

function agregarProducto({
  codigo,
  producto,
  valores,
  formato
}) {

  const nombre = String(producto ?? '').trim();

  if (!nombre) {
    errores.push('Producto sin nombre');
    return;
  }

  if (!validarColumnas(valores)) {
    errores.push(
      `Columnas inválidas: ${nombre} -> ` +
      valores.join(' | ')
    );
    return;
  }

  // Estructura de 12 columnas:
  // 0: promedio anterior
  // 1: promedio actual
  // 2: variación porcentual
  // 3-10: precios diarios
  // 11: variación porcentual

  const precioAyer = numero(valores[9]);
  const precioHoy = numero(valores[10]);

  if (
    precioHoy === null ||
    precioHoy <= 0 ||
    precioAyer === null ||
    precioAyer <= 0
  ) {
    errores.push('Precio inválido: ' + nombre);
    return;
  }

  const clave = [
    fechaObjetivo,
    'MMF2',
    nombre.toUpperCase()
  ].join('|');

  if (vistos.has(clave)) {
    errores.push('Producto duplicado: ' + clave);
    return;
  }

  vistos.add(clave);

  resultados.push({
    json: {
      fecha: fechaObjetivo,

      // Si no podemos comprobar el código
      // de una fila vertical, conservar NULL.
      codigo_cnpa: codigo ?? null,

      producto: nombre,
      mercado: 'MMF2',

      unidad: 'Kilogramo',
      equivalencia_kg: 1,

      precio: precioHoy,
      precio_ayer: precioAyer,

      // No hay volumen individual
      // en esta tabla de precios.
      volumen_t: null,
      volumen_kg: null,

      fuente: 'MIDAGRI',
      formato_origen: formato,
      tipo_prueba: 'parser_mmf2'
    }
  });

  if (formato === 'horizontal') {
    horizontales++;
  } else {
    verticales++;
  }
}

// ===========================================
// 3. PROCESAR TEXTO EXTRAÍDO
// ===========================================

